// 解析诊断请求，构建 SOP 上下文
const input = $input.first().json;
const cstTime = new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' });

const target = input.target || input.host || '';
const symptom = input.symptom || input.alert || input.message || '未知问题';
const sopType = input.sop_type || 'general';

// 根据 symptom 自动选择 SOP
let diagnosticSteps = [];
const lowerSymptom = symptom.toLowerCase();

if (lowerSymptom.includes('网络') || lowerSymptom.includes('network') || lowerSymptom.includes('连不上')) {
  diagnosticSteps = ['network_check', 'ping_test', 'dns_check', 'firewall_check'];
} else if (lowerSymptom.includes('磁盘') || lowerSymptom.includes('disk') || lowerSymptom.includes('空间')) {
  diagnosticSteps = ['disk_check', 'log_cleanup', 'large_file_scan'];
} else if (lowerSymptom.includes('CPU') || lowerSymptom.includes('负载') || lowerSymptom.includes('慢')) {
  diagnosticSteps = ['cpu_check', 'process_list', 'top_consumers'];
} else if (lowerSymptom.includes('内存') || lowerSymptom.includes('memory') || lowerSymptom.includes('OOM')) {
  diagnosticSteps = ['memory_check', 'swap_usage', 'process_memory'];
} else if (lowerSymptom.includes('备份') || lowerSymptom.includes('backup')) {
  diagnosticSteps = ['backup_status', 'backup_schedule', 'storage_check'];
} else {
  diagnosticSteps = ['health_check', 'service_status', 'log_analyze'];
}

return {
  target,
  symptom,
  sop_type: sopType,
  diagnostic_steps: diagnosticSteps,
  timestamp: cstTime,
  triggered_by: input.triggered_by || 'n8n_alert',
};

const cstTime = new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' });
const sopData = $('SOP路由').first().json;
let agentResult = {};
try { agentResult = $('请求Agent诊断').first().json || {}; } catch(e) {}

return {
  target: sopData.target,
  symptom: sopData.symptom,
  sop_type: sopData.sop_type,
  steps_executed: sopData.diagnostic_steps,
  agent_forwarded: agentResult.success || agentResult.forwarded || false,
  timestamp: cstTime,
  summary: `SOP诊断已触发: ${sopData.sop_type} → ${sopData.diagnostic_steps.join(' → ')}`,
};

// Z-OPS n8n_callback HMAC 签名 (task-c17; secret=zops.env N8N_CALLBACK_SECRET)
const crypto = require('crypto');
const secret = process.env.ZOPS_N8N_CALLBACK_SECRET || '<部署时填 zops.env 的 N8N_CALLBACK_SECRET>';
const body = JSON.stringify($input.first().json);  // 与 httpRequest raw body 完全一致
const ts = String(Math.floor(Date.now()/1000));
const nonce = crypto.randomBytes(8).toString('hex');
const payload = ['POST','/api/webhook/n8n_callback',body,ts,nonce].join('\n');
return [{ json: { __body: body, __sig: crypto.createHmac('sha256', secret).update(payload).digest('hex'), __ts: ts, __nonce: nonce } }];
